S = "Hakeem Force Academy"
QS = [
(S, "Who was the founder of the Urdu newspaper Nawa-i-Waqt?", ["Zafar Ali Khan", "Hameed Nizami", "Maulana Maududi", "Abdul Majid Salik"], 1, "Nawa-i-Waqt was launched by Hameed Nizami in 1940 as a fortnightly and became a daily in 1944.", "Its editor later became Majid Nizami, the younger brother of Hameed Nizami.", [4705]),
(S, "Which comes next in the series: A8, C10, E12, ?", ["F13", "G14", "H14", "G13"], 1, "Letters go up by 2 places (A, C, E, G) and numbers go up by 2 (8, 10, 12, 14), so the next term is G14.", "In a letter-number series, solve the letters and numbers separately.", [1659]),
(S, "What is the next prime number after 29?", ["30", "31", "33", "37"], 1, "30 is even, so it is not prime. 31 has no divisor other than 1 and itself, so it is prime.", "29 and 31 are twin primes.", [3272]),
(S, "Which letter comes next: A, C, E, G, I, K, ?", ["L", "N", "M", "O"], 2, "Each letter is 2 places after the one before it: A, C, E, G, I, K, M.", "The series uses alternate letters of the alphabet.", [4144]),
(S, "Which letter comes next: A, D, H, M, ?", ["R", "S", "T", "Q"], 1, "The gaps between letters are 3, 4, 5, so the next gap is 6. M is the 13th letter and 13 + 6 = 19, which is S.", "The gaps in this series grow by 1 each time.", [4145]),
(S, "Which number comes next: 1, 3, 7, 13, ?", ["19", "21", "20", "23"], 1, "The differences are 2, 4, 6, so the next difference is 8. 13 + 8 = 21.", "The differences form an even-number series.", [4173]),
(S, "Which number comes next: 1, 3, 7, 15, 31, ?", ["47", "62", "63", "61"], 2, "Each term is double the previous one plus 1: 31 x 2 + 1 = 63.", "These numbers are one less than powers of 2.", [4174]),
(S, "Which number comes next: 1/2, 1/4, 1/8, ?", ["1/10", "1/16", "1/12", "1/6"], 1, "Each term is half of the term before it, so 1/8 x 1/2 = 1/16.", "This is a geometric series with common ratio 1/2.", [4175]),
(S, "Which comes next in the series: b 5 g 8 l 11 q 14 ?", ["v", "u", "w", "17"], 0, "The letters go up by 5 places (b, g, l, q, v) and the numbers go up by 3 (5, 8, 11, 14, 17). The next item is the letter v, then 17.", "Alternating letter and number series should be solved separately.", [4182]),
(S, "In which city is Nishtar Park situated?", ["Lahore", "Multan", "Karachi", "Peshawar"], 2, "Nishtar Park is a large park and ground in the Saddar area of Karachi, named after Sardar Abdur Rab Nishtar.", "Nishtar Hospital, in contrast, is in Multan.", [3751]),
(S, "Which was the first battle of the Muslims against a non-Arab power?", ["Battle of Muta", "Battle of Tabuk", "Battle of Hunain", "Battle of Khandaq"], 0, "The Battle of Muta in 8 AH (629 CE) was fought against the Byzantine (Roman) army, a non-Arab power.", "Zaid bin Haritha was the first commander of the Muslim army at Muta.", [1314]),
(S, "On what date did India conduct its first nuclear test?", ["18 May 1974", "11 May 1998", "28 May 1998", "18 May 1984"], 0, "India carried out its first nuclear test, code named Smiling Buddha, at Pokhran on 18 May 1974.", "India's second series of tests at Pokhran was in May 1998.", [3509]),
(S, "In which year did Pakistan conduct its nuclear tests?", ["1974", "1996", "1998", "2001"], 2, "Pakistan carried out its nuclear tests in the Chagai hills on 28 May 1998, soon after India's tests.", "Pakistan became the first Muslim country with nuclear weapons.", [2266]),
(S, "What is the range of the numbers 69 and 9?", ["78", "69", "9", "60"], 3, "Range = largest value minus smallest value = 69 - 9 = 60.", "Range is a measure of how spread out the data is.", [3332]),
(S, "What is the antonym of obligation?", ["Duty", "Freedom", "Burden", "Commitment"], 1, "Obligation means something one must do, so its opposite is freedom or choice.", "Duty and commitment are synonyms of obligation.", [2987]),
(S, "What is the meaning of the word obscure?", ["Clear", "Famous", "Unclear or not well known", "Bright"], 2, "Obscure means hard to understand or see, or not well known.", "Its antonym is clear or obvious.", [3043, 1132]),
(S, "What is the antonym of obvious?", ["Evident", "Plain", "Clear", "Obscure"], 3, "Obvious means easily seen or understood, so its opposite is obscure, meaning unclear or hidden.", "Evident, plain and clear are synonyms of obvious.", [2988]),
(S, "Which word is a synonym of obvious?", ["Hidden", "Evident", "Doubtful", "Vague"], 1, "Obvious means easy to see or understand, which is the same as evident.", "Other synonyms are clear, plain and apparent.", [1165]),
(S, "Which country hosted the first FIFA World Cup in 1930?", ["Brazil", "Italy", "Uruguay", "France"], 2, "Uruguay hosted the first World Cup in 1930 and also won it by beating Argentina in the final.", "Italy won the second World Cup in 1934.", [2145]),
(S, "Where was the G20 summit of 2023 held?", ["Bali, Indonesia", "Rome, Italy", "Riyadh, Saudi Arabia", "New Delhi, India"], 3, "India held the 2023 G20 summit in New Delhi on 9 and 10 September 2023.", "The 2022 summit was in Bali, Indonesia, and the 2024 summit in Rio de Janeiro, Brazil.", [3706]),
(S, "Which organization prepares the official map of Pakistan?", ["Survey of Pakistan", "Pakistan Meteorological Department", "Geological Survey of Pakistan", "SUPARCO"], 0, "The Survey of Pakistan, under the Ministry of Defence, is the national mapping organization that prepares official maps.", "It was created in 1947 as successor to the Survey of India and is based in Rawalpindi.", [1635]),
(S, "Which are the official languages of the Organisation of Islamic Cooperation (OIC)?", ["Arabic, English and French", "Arabic and Urdu", "Arabic, Persian and Turkish", "Arabic only"], 0, "The OIC Charter names Arabic, English and French as its three official languages.", "The OIC headquarters is in Jeddah, Saudi Arabia.", [3282]),
(S, "What was the old (first) capital of Pakistan?", ["Lahore", "Rawalpindi", "Karachi", "Peshawar"], 2, "Karachi was the capital from 1947 until the capital moved to Rawalpindi temporarily and then to Islamabad in the 1960s.", "Islamabad became the capital as a planned city built from 1960.", [3538]),
(S, "Ali is 6 years old and his sister is 3 times his age. How old is his sister?", ["9 years", "12 years", "24 years", "18 years"], 3, "Sister's age = 3 x 6 = 18 years.", "Here times as old means multiply.", [1972]),
]
